import json, csv, re, statistics as st
tr = [json.loads(l) for l in open('data/judge_transcripts.jsonl')]
rows = list(csv.DictReader(open('data/scores.csv')))
tscore = {t['rating_id']: int(re.findall(r'FINAL SCORE:\s*(\d+)', t['judge_output'])[0]) for t in tr}
def effects(getscore, label):
    by = {}
    for r in rows:
        by.setdefault(r['response_id'], {})[r['displayed_label']] = getscore(r)
    d = {k: v['atlas-7'] - v['nova-3'] for k, v in by.items()}
    vals = list(d.values())
    m = st.mean(vals); sd = st.stdev(vals); n=len(vals)
    print(label, 'n=',n, 'mean=',round(m,3), 'sd=',round(sd,3), 'se=',round(sd/n**.5,3),
          '95%CI~', round(m-2.045*sd/n**.5,3), round(m+2.045*sd/n**.5,3))
    print(' nonzero:', sum(1 for x in vals if x!=0), 'pos:', sum(1 for x in vals if x>0), 'neg:', sum(1 for x in vals if x<0))
    return d
d_csv = effects(lambda r: int(r['score']), 'CSV')
d_tr = effects(lambda r: tscore[r['rating_id']], 'TRANSCRIPT')
# session-order split
sess = {}
for r in rows:
    sess.setdefault(r['response_id'], {})[r['displayed_label']] = int(r['session'])
for name, d in [('csv',d_csv),('tr',d_tr)]:
    a = [d[k] for k in d if sess[k]['atlas-7']==1]
    b = [d[k] for k in d if sess[k]['atlas-7']==2]
    print(name, 'atlas-in-session1 (n=%d) mean=%.3f' % (len(a), st.mean(a)), '| atlas-in-session2 (n=%d) mean=%.3f' % (len(b), st.mean(b)))
# session means by label
for lab in ['atlas-7','nova-3']:
    for s in [1,2]:
        v=[tscore[r['rating_id']] for r in rows if r['displayed_label']==lab and r['session']==str(s)]
        print('transcript', lab, 'session', s, len(v), round(st.mean(v),2))
print(sorted(d_tr.items()))
